def has_duplicate(nums):
    seen = set()
    for x in nums:
        if x in seen:
            return True
        seen.add(x)
    return False
```
O(n) time, O(n) space. Sorting first and comparing neighbours is O(n log n) time but O(1) extra space.

```python
def is_anagram(s, t):
    if len(s) != len(t):
        return False
    counts = {}
    for a, b in zip(s, t):
        counts[a] = counts.get(a, 0) + 1
        counts[b] = counts.get(b, 0) - 1
    return all(v == 0 for v in counts.values())
```

```python
def two_sum(nums, target):
    index_of = {}
    for j, x in enumerate(nums):
        i = index_of.get(target - x)
        if i is not None:
            return [i, j]
        index_of[x] = j
    return []
```

```python
from collections import defaultdict

def group_anagrams(words):
    groups = defaultdict(list)
    for w in words:
        counts = [0] * 26
        for ch in w:
            counts[ord(ch) - ord("a")] += 1
        groups[tuple(counts)].append(w)
    return list(groups.values())
```

