import math

def check_derivative(f, f_prime, xs, h=1e-5, tol=1e-6):
    for x in xs:
        numeric = (f(x + h) - f(x - h)) / (2 * h)
        if abs(numeric - f_prime(x)) > tol * max(1.0, abs(f_prime(x))):
            return False
    return True

print(check_derivative(lambda x: 5 * x**4 - 3 * x + 2, lambda x: 20 * x**3 - 3, [0.5, 1, 2]))
```

