tasks.solution:
```cpp
#include <iostream>
#include <vector>

int index_of_max(std::vector<int> v) {
    if (v.empty()) return -1;
    int best = v[0];
    int best_i = 0;
    for (std::size_t i = 1; i < v.size(); ++i) {
        if (v[i] > best) {
            best = v[i];
            best_i = static_cast<int>(i);
        }
    }
    return best_i;
}

int main() {
    std::cout << index_of_max({-5, -2, -9}) << '\n';   // 1
    return 0;
}
```
The root cause: the running maximum was seeded with a value (0) that isn't in the data.

