```cpp
#include <cassert>
#include <iostream>

enum Mode { OFF, CHASE, BLINK_ALL, BAR };

Mode next_mode(Mode m) {
    return static_cast<Mode>((m + 1) % 4);
}

int bar_count(int raw) {          // 0..1023 -> 0..3 LEDs
    if (raw < 0) raw = 0;
    if (raw > 1023) raw = 1023;
    return raw * 4 / 1024;
}

int main() {
    assert(next_mode(OFF) == CHASE);
    assert(next_mode(BAR) == OFF);
    assert(bar_count(0) == 0);
    assert(bar_count(255) == 0);
    assert(bar_count(256) == 1);
    assert(bar_count(1023) == 3);
    assert(bar_count(5000) == 3);
    std::cout << "logic tests pass\n";
    return 0;
}
